function evolutionPreview(p){return p.forms.map(f=>{const d=formStats(p,f),order=Object.keys(stages);return `<details class="box"><summary>${esc(f.stage)} // ${esc(f.name)}</summary><div class="portrait"><img src="${esc(f.image)}" alt="${esc(f.name)}" referrerpolicy="no-referrer"></div>${row('ATRIBUTO DIGITAL',f.digital)}${row('ELEMENTO',f.element)}${row('CLASSIFICAÇÃO',f.classification)}${digiKeys.map(k=>row(labels[k],f.digi[k])).join('')}${row('PV MÁXIMOS',d.pv)}${row('DANO',d.damage)}${row('ESQUIVA',d.dodge)}${row('USOS COMPARTILHADOS',d.uses)}${p.qualities.filter(q=>q.stage===f.stage).map(q=>row('QUALIDADE / RANK '+q.rank,q.name)).join('')}${allAttacks(p,s).filter(t=>order.indexOf(t.stage)<=order.indexOf(f.stage)).map(t=>row('ATAQUE / RANK '+t.rank,t.name+' / '+t.element+' / '+t.effects.map(e=>e.name+(e.element?' ('+e.element+')':'')).join('; '))).join('')}</details>`}).join('')}
function selectPreviewTab(key,focus=false){
  if(!['human','digimon'].includes(key))return;
  previewTab=key;
  for(const tab of document.querySelectorAll('[data-preview-tab]')){
    const active=tab.dataset.previewTab===key;
    tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;
    document.getElementById(tab.getAttribute('aria-controls')).hidden=!active;
    if(active&&focus)tab.focus();
  }
}
