function navigate(n,focus){if(n===9)setTerminalMode('update');else if(terminalMode==='launcher')setTerminalMode('registration');history.replaceState(null,'',terminalMode==='update'?'#update':'#registration');if(n===4)n=5;if(n>9)n=8;step=n;const hints=['Comece aqui e avance no seu ritmo. Seus dados são salvos automaticamente.','Defina a identidade e distribua as características do Humano.','Escolha um Arquétipo para conhecer sua habilidade e sugestões.','Complete os traços que dão personalidade ao personagem.','','Escolha a espécie para carregar sua imagem. A aparência do Digivice é opcional.','Conte como o Humano e seu parceiro se conheceram.','Confira as pendências. Clique em uma delas para ir ao campo correspondente.','Copie a ficha para o fórum e exporte um JSON como cópia.','Recupere a ficha anterior, aplique as recompensas e copie os dois códigos.'];$('#journey-title').textContent='Você está em: '+(steps[n]||'Atualização').toLocaleLowerCase('pt-BR');$('#journey-hint').textContent=hints[n];$('#journey-count').textContent=n===9?'Progressão da parceria':n===0?'Vamos começar':n===8?'Após a criação':'Etapa '+displayStep(n)+' de 7';if(n===5)selectPreviewTab('digimon');else if(n>=1&&n<=6)selectPreviewTab('human');$('#steps').innerHTML=steps.map((v,i)=>v&&i<9?`<button data-step="${i}" class="${step===i?'active':''}" ${step===i?'aria-current="step"':''}><span>${String(displayStep(i)).padStart(2,'0')}</span>${v}</button>`:'').join('');renderEditor();updateFields();document.querySelector('.navigation').hidden=n===9;document.querySelector('aside .eyebrow').textContent=n===9?'DATA UPDATE':'DATA REGISTRATION';document.querySelectorAll('[data-terminal-mode]').forEach(b=>b.setAttribute('aria-pressed',String(terminalMode===b.dataset.terminalMode)));document.querySelector('.workspace-top span:last-child').textContent=n===9?'UPDATE / V.02':'REGISTRATION / V.01';if(focus)setTimeout(()=>document.getElementById(focus)?.focus(),0)}
